/**
 * Errors surfaced to Swift (`throws`) and Kotlin (exceptions).
 *
 * `reason` is for logs and diagnostics, not for end users: map the variant
 * to localized UI text on each platform. (The field must not be called
 * `message`: it would clash with `Throwable.message` in the Kotlin bindings.)
 */
public 
enum NolvaError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case InvalidArgument(reason: String
    )
    case NotFound(reason: String
    )
    case Unsupported(reason: String
    )
    case Storage(reason: String
    )
    /**
     * The data changed while the operation ran; it no longer applies.
     */
    case Conflict(reason: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension NolvaError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeNolvaError: FfiConverterRustBuffer {
    typealias SwiftType = NolvaError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> NolvaError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidArgument(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .NotFound(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Unsupported(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Storage(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Conflict(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: NolvaError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidArgument(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .NotFound(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Unsupported(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Storage(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Conflict(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeNolvaError_lift(_ buf: RustBuffer) throws -> NolvaError {
    return try FfiConverterTypeNolvaError.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeNolvaError_lower(_ value: NolvaError) -> RustBuffer {
    return FfiConverterTypeNolvaError.lower(value)
}


